INSERT INTO necessidades (id,rotulo,titulo,intro,fecho) VALUES ('infra','Infraestrutura','Melhoria da infraestrutura','Um dos principais pontos de atenção é a estrutura dos espaços destinados aos cavalos. Durante a visita, observamos instalações com dimensões reduzidas, disposição inadequada e presença de entulhos nos ambientes.','Uma infraestrutura adequada é essencial para preservar a saúde, o conforto e a qualidade de vida dos animais.');
INSERT INTO necessidade_itens (id,necessidade_id,grupo,item,ordem) VALUES (1,'infra','O que precisa melhorar?','Construção ou reforma de baias, garantindo dimensões adequadas aos animais',0);
INSERT INTO necessidade_itens (id,necessidade_id,grupo,item,ordem) VALUES (2,'infra','O que precisa melhorar?','Melhor organização e distribuição dos espaços',1);
INSERT INTO necessidade_itens (id,necessidade_id,grupo,item,ordem) VALUES (3,'infra','O que precisa melhorar?','Ambientes limpos, arejados e protegidos das condições climáticas',2);
INSERT INTO necessidade_itens (id,necessidade_id,grupo,item,ordem) VALUES (4,'infra','O que precisa melhorar?','Retirada de entulhos e materiais descartados',3);
INSERT INTO necessidade_itens (id,necessidade_id,grupo,item,ordem) VALUES (5,'infra','O que precisa melhorar?','Espaços apropriados para descanso, alimentação e movimentação dos cavalos',4);
INSERT INTO necessidades (id,rotulo,titulo,intro,fecho) VALUES ('montaria','Equipamentos de montaria','Renovação dos equipamentos de montaria','Os equipamentos usados nas sessões também merecem atenção. Alguns dos materiais disponíveis apresentam sinais de desgaste e precisam ser substituídos para garantir melhores condições de uso.','É importante adquirir selas adaptadas às necessidades dos praticantes, considerando as particularidades de pessoas com Transtorno do Espectro Autista (TEA) e de outras condições. Elas devem favorecer o posicionamento, a estabilidade e o conforto durante as sessões, respeitando as necessidades individuais.');
INSERT INTO necessidade_itens (id,necessidade_id,grupo,item,ordem) VALUES (6,'montaria','Materiais necessários','Selas adequadas à prática da equoterapia',0);
INSERT INTO necessidade_itens (id,necessidade_id,grupo,item,ordem) VALUES (7,'montaria','Materiais necessários','Mantas e protetores',1);
INSERT INTO necessidade_itens (id,necessidade_id,grupo,item,ordem) VALUES (8,'montaria','Materiais necessários','Cabeçadas e rédeas',2);
INSERT INTO necessidade_itens (id,necessidade_id,grupo,item,ordem) VALUES (9,'montaria','Materiais necessários','Estribos e acessórios de montaria',3);
INSERT INTO necessidade_itens (id,necessidade_id,grupo,item,ordem) VALUES (10,'montaria','Materiais necessários','Equipamentos de apoio e segurança',4);
INSERT INTO necessidades (id,rotulo,titulo,intro,fecho) VALUES ('veterinario','Materiais veterinários','Materiais para os cuidados veterinários','Além da infraestrutura e dos equipamentos de montaria, é necessário manter materiais para os cuidados diários e para a assistência veterinária dos cavalos.','A disponibilidade desses recursos contribui para uma rotina de cuidados mais organizada, com maior atenção à saúde dos animais e assistência adequada quando necessário.');
