INSERT INTO parceiros (id,titulo,tag,destaque,intro,lista_titulo,publico_titulo,publico,fecho) VALUES ('apadrinhe','Apadrinhe um cavalo','Contribuição mensal','Uma forma de ajudar continuamente.','O apadrinhamento solidário permite que pessoas contribuam mensalmente com o cuidado e a manutenção dos cavalos que participam das atividades de equoterapia. Com uma contribuição voluntária, você ajuda a custear despesas como alimentação, cuidados veterinários, medicamentos, materiais de higiene e manutenção dos equipamentos.','Como participar?',NULL,NULL,'Você não precisa doar muito para fazer a diferença. A união de pequenas contribuições pode garantir grandes melhorias.');
INSERT INTO parceiro_itens (id,parceiro_id,item,ordem) VALUES (1,'apadrinhe','Escolha uma contribuição mensal que caiba no seu orçamento',0);
INSERT INTO parceiro_itens (id,parceiro_id,item,ordem) VALUES (2,'apadrinhe','Entre em contato com a organização do projeto',1);
INSERT INTO parceiro_itens (id,parceiro_id,item,ordem) VALUES (3,'apadrinhe','Receba informações sobre a destinação dos recursos e os resultados alcançados',2);
INSERT INTO parceiros (id,titulo,tag,destaque,intro,lista_titulo,publico_titulo,publico,fecho) VALUES ('alimentacao','Doe alimentação','Doação de produtos','Ajude a manter os cavalos bem alimentados!','A alimentação adequada é indispensável para a saúde, a disposição e a qualidade de vida dos cavalos. Você pode contribuir com a aquisição ou doação de alimentos e insumos necessários à rotina dos animais.','O que pode ser doado?',NULL,NULL,'Uma alimentação de qualidade também é uma forma de cuidado e respeito.');
INSERT INTO parceiro_itens (id,parceiro_id,item,ordem) VALUES (4,'alimentacao','Feno e volumosos adequados',0);
