INSERT INTO parceiros (id,titulo,tag,destaque,intro,lista_titulo,publico_titulo,publico,fecho) VALUES ('empresa','Seja um parceiro do bem','Parcerias e patrocínios','Sua empresa também pode fazer parte dessa transformação!','Empresas, comércios, produtores rurais, profissionais autônomos e instituições podem contribuir com o fortalecimento da equoterapia por meio de parcerias e patrocínios.','As contribuições podem acontecer de diferentes maneiras','Quem pode ser parceiro?','Clínicas veterinárias, lojas agropecuárias, casas de ração, laboratórios, empresas locais, produtores rurais, estabelecimentos comerciais e outras instituições interessadas na causa.','A responsabilidade social das empresas também pode transformar realidades.');
INSERT INTO parceiro_itens (id,parceiro_id,item,ordem) VALUES (8,'empresa','Patrocínio financeiro mensal ou pontual',0);
INSERT INTO parceiro_itens (id,parceiro_id,item,ordem) VALUES (9,'empresa','Doação de produtos e materiais',1);
INSERT INTO parceiro_itens (id,parceiro_id,item,ordem) VALUES (10,'empresa','Descontos especiais na aquisição de insumos',2);
INSERT INTO parceiro_itens (id,parceiro_id,item,ordem) VALUES (11,'empresa','Disponibilização de serviços profissionais',3);
INSERT INTO parceiro_itens (id,parceiro_id,item,ordem) VALUES (12,'empresa','Apoio na divulgação das campanhas',4);
INSERT INTO parceiros (id,titulo,tag,destaque,intro,lista_titulo,publico_titulo,publico,fecho) VALUES ('veterinaria','Faça parte da rede veterinária solidária','Prestação de serviços profissionais','Conhecimento e cuidado também são formas de doação!','A saúde dos cavalos é fundamental para que as atividades de equoterapia aconteçam com segurança e qualidade. Por isso, buscamos profissionais e estabelecimentos veterinários dispostos a contribuir com assistência e acompanhamento dos animais.','Como você pode contribuir?','Quem pode participar?','Médicos-veterinários, clínicas, hospitais veterinários, laboratórios, profissionais de odontologia equina, ferradores e demais especialistas.','Seu conhecimento pode ajudar a proporcionar uma vida mais saudável e digna aos nossos cavalos.');
INSERT INTO parceiro_itens (id,parceiro_id,item,ordem) VALUES (13,'veterinaria','Consultas e avaliações clínicas',0);
INSERT INTO parceiro_itens (id,parceiro_id,item,ordem) VALUES (14,'veterinaria','Atendimento odontológico equino',1);
INSERT INTO parceiro_itens (id,parceiro_id,item,ordem) VALUES (15,'veterinaria','Acompanhamento nutricional',2);
