INSERT INTO parceiro_itens (id,parceiro_id,item,ordem) VALUES (19,'veterinaria','Orientações sobre manejo, higiene e bem-estar',6);
INSERT INTO parceiros (id,titulo,tag,destaque,intro,lista_titulo,publico_titulo,publico,fecho) VALUES ('instituicao','Seja uma instituição parceira','Apoio institucional e acadêmico','Juntos, podemos ampliar o alcance dessa iniciativa!','Universidades, faculdades, instituições de ensino e organizações podem contribuir com conhecimento, infraestrutura, projetos de extensão e ações que fortaleçam a equoterapia.','Possibilidades de colaboração',NULL,NULL,'A parceria entre instituições de ensino e a APAE pode aproximar a comunidade acadêmica das necessidades sociais, proporcionando experiências práticas aos estudantes e benefícios à instituição. Conhecimento compartilhado também gera transformação.');
